package ru.murad.yourmarket.service;import org.junit.jupiter.api.Test;import ru.murad.yourmarket.exception.*;import ru.murad.yourmarket.model.AdvertisementChannelMessage;import ru.murad.yourmarket.service.impl.ChannelMessageDeletionServiceImpl;import ru.murad.yourmarket.telegram.TelegramGateway;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class ChannelMessageDeletionServiceTest {ChannelMessageDeletionTransactionService tx=mock(ChannelMessageDeletionTransactionService.class);TelegramGateway tg=mock(TelegramGateway.class);ChannelMessageDeletionServiceImpl service=new ChannelMessageDeletionServiceImpl(tx,tg);UUID ad=UUID.randomUUID(),row=UUID.randomUUID(),op=UUID.randomUUID();
@Test void onlyStructuredAbsentIsSuccess(){when(tx.candidates(ad)).thenReturn(List.of(row));when(tx.claim(row)).thenReturn(msg());doThrow(new TelegramMessageAlreadyAbsentException("absent",null)).when(tg).deleteChannelMessage(1);when(tx.allDeleted(ad)).thenReturn(true);assertTrue(service.deleteAll(ad));verify(tx).complete(row,op);}
@Test void similarTextIsFailure(){when(tx.candidates(ad)).thenReturn(List.of(row));when(tx.claim(row)).thenReturn(msg());doThrow(new RuntimeException("message to delete not found")).when(tg).deleteChannelMessage(1);when(tx.allDeleted(ad)).thenReturn(false);assertFalse(service.deleteAll(ad));verify(tx).fail(row,op,"message to delete not found");}
private AdvertisementChannelMessage msg(){return AdvertisementChannelMessage.builder().id(row).advertisementId(ad).channelMessageId(1).position(0).deleteOperationId(op).build();}}
